-- Sports Hub: full database setup. Generated by supabase/bundle.sh — edit the migrations, not this file.
-- Paste once into Supabase Dashboard → SQL Editor → Run, on an empty project.

-- ===== migrations/0001_profiles_rbac.sql =====
-- Sports Hub: roles and the fan/staff firewall.
-- The UI hides links; this file is what actually stops a fan from reading staff data.

create type public.app_role as enum ('fan', 'player', 'medical', 'club_admin', 'bfa_admin');

create table public.clubs (
  id    uuid primary key default gen_random_uuid(),
  name  text not null unique
);

create table public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  role       public.app_role not null default 'fan',
  club_id    uuid references public.clubs (id),
  full_name  text,
  created_at timestamptz not null default now(),
  -- staff belong to a club; fans and the federation do not have to
  constraint staff_has_club check (role in ('fan', 'bfa_admin') or club_id is not null)
);
create index profiles_club_idx on public.profiles (club_id);

alter table public.clubs enable row level security;
alter table public.profiles enable row level security;

-- Helpers run as definer so policies can read the caller's role without recursing into profiles RLS.
create function public.my_role() returns public.app_role
  language sql stable security definer set search_path = '' as
  $$ select role from public.profiles where id = auth.uid() $$;

create function public.my_club() returns uuid
  language sql stable security definer set search_path = '' as
  $$ select club_id from public.profiles where id = auth.uid() $$;

revoke execute on function public.my_role(), public.my_club() from public, anon;
grant execute on function public.my_role(), public.my_club() to authenticated;

create policy "clubs are public" on public.clubs for select to anon, authenticated using (true);

create policy "read own profile" on public.profiles for select to authenticated
  using (id = (select auth.uid()));

create policy "club admin reads own club staff" on public.profiles for select to authenticated
  using ((select public.my_role()) = 'club_admin' and club_id = (select public.my_club()));

-- Users may edit their name only. role and club_id change through the service role (admin panel), never from the client.
create policy "update own name" on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
revoke update on public.profiles from authenticated;
grant update (full_name) on public.profiles to authenticated;

-- Every new sign-up starts as a fan.
create function public.handle_new_user() returns trigger
  language plpgsql security definer set search_path = '' as
  $$ begin insert into public.profiles (id) values (new.id); return new; end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ===== migrations/0002_delete_my_account.sql =====
-- PDPL right to erasure: a signed-in user deletes their own account; profiles go with it (on delete cascade).
create function public.delete_my_account() returns void
  language sql security definer set search_path = '' as
  $$ delete from auth.users where id = auth.uid() $$;

revoke execute on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- ===== migrations/0003_fan_zone.sql =====
-- Fan Zone data: leagues, tables, fixtures, man-of-the-match votes, each fan's club.
-- Public data is readable by anyone; writes go through the service role (admin panel / import), never the app.
-- is_demo marks rows that are illustrative; the app shows «بيانات تجريبية» while any is present.

create table public.leagues (
  id    text primary key,
  name  text not null,
  tier  smallint not null
);

create table public.league_entries (
  league_id text not null references public.leagues (id) on delete cascade,
  club_id   uuid not null references public.clubs (id) on delete cascade,
  played    smallint not null default 0 check (played >= 0),
  won       smallint not null default 0 check (won >= 0),
  drawn     smallint not null default 0 check (drawn >= 0),
  lost      smallint not null default 0 check (lost >= 0),
  gf        smallint not null default 0 check (gf >= 0),
  ga        smallint not null default 0 check (ga >= 0),
  is_demo   boolean not null default true,
  primary key (league_id, club_id),
  check (played = won + drawn + lost)
);

create table public.players (
  id       uuid primary key default gen_random_uuid(),
  club_id  uuid not null references public.clubs (id) on delete cascade,
  name     text not null,
  num      smallint check (num between 1 and 99),
  pos      text not null
);
create index players_club_idx on public.players (club_id);

create table public.matches (
  id        uuid primary key default gen_random_uuid(),
  league_id text not null references public.leagues (id),
  home_id   uuid not null references public.clubs (id),
  away_id   uuid not null references public.clubs (id),
  venue     text not null,
  kickoff   timestamptz not null,
  is_demo   boolean not null default true,
  check (home_id <> away_id)
);
create index matches_kickoff_idx on public.matches (kickoff);

create table public.motm_candidates (
  match_id  uuid not null references public.matches (id) on delete cascade,
  player_id uuid not null references public.players (id) on delete cascade,
  primary key (match_id, player_id)
);

-- One vote per fan per match, enforced by the primary key, not by the UI.
create table public.motm_votes (
  match_id   uuid not null,
  voter_id   uuid not null default auth.uid() references auth.users (id) on delete cascade,
  player_id  uuid not null,
  created_at timestamptz not null default now(),
  primary key (match_id, voter_id),
  foreign key (match_id, player_id) references public.motm_candidates (match_id, player_id) on delete cascade
);

alter table public.profiles add column fav_club_id uuid references public.clubs (id);
grant update (fav_club_id) on public.profiles to authenticated;

alter table public.leagues enable row level security;
alter table public.league_entries enable row level security;
alter table public.players enable row level security;
alter table public.matches enable row level security;
alter table public.motm_candidates enable row level security;
alter table public.motm_votes enable row level security;

create policy "public read" on public.leagues for select to anon, authenticated using (true);
create policy "public read" on public.league_entries for select to anon, authenticated using (true);
create policy "public read" on public.players for select to anon, authenticated using (true);
create policy "public read" on public.matches for select to anon, authenticated using (true);
create policy "public read" on public.motm_candidates for select to anon, authenticated using (true);

-- Read-only from the app: no insert/update/delete grants for anon/authenticated on public data.
revoke insert, update, delete on public.leagues, public.league_entries, public.players,
  public.matches, public.motm_candidates from anon, authenticated;

-- A fan sees and casts only their own vote, and only before kickoff + 2h (voting window).
create policy "read own vote" on public.motm_votes for select to authenticated
  using (voter_id = (select auth.uid()));
create policy "vote once in window" on public.motm_votes for insert to authenticated
  with check (
    voter_id = (select auth.uid())
    and exists (select 1 from public.matches m where m.id = match_id and now() < m.kickoff + interval '2 hours')
  );
revoke update, delete on public.motm_votes from anon, authenticated;
revoke all on public.motm_votes from anon;

-- Totals are public; who voted for whom is not.
create function public.motm_tally(p_match uuid) returns table (player_id uuid, votes bigint)
  language sql stable security definer set search_path = '' as
  $$ select c.player_id, count(v.voter_id)
     from public.motm_candidates c
     left join public.motm_votes v on v.match_id = c.match_id and v.player_id = c.player_id
     where c.match_id = p_match
     group by c.player_id $$;
grant execute on function public.motm_tally(uuid) to anon, authenticated;

-- ===== migrations/0004_data_provenance.sql =====
-- Where did this number come from, and when was it last touched? The app shows both next to real data.
alter table public.league_entries add column source text, add column updated_at timestamptz not null default now();
alter table public.matches        add column source text, add column updated_at timestamptz not null default now();

create function public.touch_updated_at() returns trigger language plpgsql set search_path = '' as
  $$ begin new.updated_at = now(); return new; end $$;

create trigger league_entries_touch before update on public.league_entries
  for each row execute function public.touch_updated_at();
create trigger matches_touch before update on public.matches
  for each row execute function public.touch_updated_at();

-- ===== migrations/0005_club_federation.sql =====
-- Club and federation workspaces. Tenant isolation is the product: a club sees its own people and money and nobody else's,
-- and the federation sees only what a club chooses to submit (the season finance report), never player-level pay.

alter table public.clubs add column is_fictional boolean not null default false; -- demo-only clubs: never offered in the fan club picker

-- A composite key lets child tables prove "this player belongs to this club" in the database, not in app code.
alter table public.players add constraint players_id_club_key unique (id, club_id);

create table public.rules (
  key     text primary key,
  value   numeric not null,
  label   text not null,
  is_demo boolean not null default true
);
insert into public.rules (key, value, label) values
  ('ffp_wage_ratio_limit', 0.70, 'الحد الأعلى لنسبة الأجور إلى الإيرادات (قيمة تجريبية، مو قاعدة رسمية)');

create table public.contracts (
  id               uuid primary key default gen_random_uuid(),
  player_id        uuid not null,
  club_id          uuid not null,
  starts_on        date not null,
  ends_on          date not null,
  monthly_wage_bhd numeric(10, 3) not null check (monthly_wage_bhd >= 0),
  is_demo          boolean not null default true,
  check (ends_on > starts_on),
  foreign key (player_id, club_id) references public.players (id, club_id) on delete cascade
);
create index contracts_club_end_idx on public.contracts (club_id, ends_on);

create table public.player_status (
  player_id  uuid primary key,
  club_id    uuid not null,
  status     text not null check (status in ('fit', 'doubtful', 'injured', 'suspended')),
  note       text,
  updated_at timestamptz not null default now(),
  is_demo    boolean not null default true,
  foreign key (player_id, club_id) references public.players (id, club_id) on delete cascade
);
create trigger player_status_touch before update on public.player_status
  for each row execute function public.touch_updated_at();

create table public.club_finance_reports (
  club_id      uuid not null references public.clubs (id) on delete cascade,
  season       text not null,
  revenue_bhd  numeric(14, 3) not null check (revenue_bhd >= 0),
  wages_bhd    numeric(14, 3) not null check (wages_bhd >= 0),
  submitted_at timestamptz not null default now(),
  submitted_by uuid default auth.uid() references auth.users (id) on delete set null,
  is_demo      boolean not null default true,
  primary key (club_id, season)
);
create function public.touch_submitted_at() returns trigger language plpgsql set search_path = '' as
  $$ begin new.submitted_at = now(); return new; end $$;
create trigger finance_touch before update on public.club_finance_reports
  for each row execute function public.touch_submitted_at();

alter table public.rules enable row level security;
alter table public.contracts enable row level security;
alter table public.player_status enable row level security;
alter table public.club_finance_reports enable row level security;

-- Supabase hands new tables to anon/authenticated by default: start from nothing, then grant exactly what each role needs.
revoke all on public.rules, public.contracts, public.player_status, public.club_finance_reports from anon, authenticated;
grant select on public.rules, public.contracts, public.player_status, public.club_finance_reports to authenticated;
grant update (status, note) on public.player_status to authenticated;
grant insert (club_id, season, revenue_bhd, wages_bhd), update (revenue_bhd, wages_bhd) on public.club_finance_reports to authenticated;

create policy "rules readable by signed-in users" on public.rules for select to authenticated using (true);

-- Pay: the club's own administrators only. Medical staff, players, fans and the federation never see it.
create policy "club admin reads own contracts" on public.contracts for select to authenticated
  using ((select public.my_role()) = 'club_admin' and club_id = (select public.my_club()));

-- Availability is health-adjacent: own club's administrators and medical staff.
create policy "own club staff read status" on public.player_status for select to authenticated
  using ((select public.my_role()) in ('club_admin', 'medical') and club_id = (select public.my_club()));
create policy "own club staff update status" on public.player_status for update to authenticated
  using ((select public.my_role()) in ('club_admin', 'medical') and club_id = (select public.my_club()))
  with check ((select public.my_role()) in ('club_admin', 'medical') and club_id = (select public.my_club()));

-- Finance report: the club writes its own; the federation reads every submitted one. Submitting IS the consent.
create policy "club admin reads own report" on public.club_finance_reports for select to authenticated
  using ((select public.my_role()) = 'club_admin' and club_id = (select public.my_club()));
create policy "federation reads submitted reports" on public.club_finance_reports for select to authenticated
  using ((select public.my_role()) = 'bfa_admin');
create policy "club admin submits own report" on public.club_finance_reports for insert to authenticated
  with check ((select public.my_role()) = 'club_admin' and club_id = (select public.my_club()));
create policy "club admin amends own report" on public.club_finance_reports for update to authenticated
  using ((select public.my_role()) = 'club_admin' and club_id = (select public.my_club()))
  with check ((select public.my_role()) = 'club_admin' and club_id = (select public.my_club()));

